<?php
/** Administrator-only reviewer management. */
defined('ABSPATH') || exit;
use AutoAgora\Dealer\Review;
use AutoAgora\Dealer\Reviewer;
use AutoAgora\Dealer\Workspace;
if (!Review::admin()) { exit; }
?>
<section class="card agw-panel agw-review-access"><h2 class="card-title">Reviewers</h2><p>Test workspace only. No WordPress admin or real customer data.</p>
<form class="agw-access-form" method="post" action="<?php echo esc_url(Workspace::url()); ?>"><?php Workspace::nonce(); ?><input type="hidden" name="workspace_action" value="create_reviewer"><label class="form-label agw-field">Username<input class="form-control" name="reviewer_username" type="text" required minlength="3" maxlength="32" pattern="[a-z0-9][a-z0-9_.\-]{2,31}" placeholder="e.g. alekos" autocomplete="off" autocapitalize="none"></label><label class="form-label agw-field">Expires after<select class="form-select" name="reviewer_days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="90">90 days</option></select></label><button class="btn btn-primary">Create reviewer login</button></form>
<div class="alert alert-secondary agw-dialog-note"><?php echo Workspace::icon('shield-check'); ?><span>Password shown once. No email sent. Sessions last one hour.</span></div>
<div class="table-responsive agw-table-wrap agw-reviewer-list"><table class="table table-vcenter table-hover agw-table"><thead><tr><th>Username</th><th>Access</th><th>Expires</th><th><span class="agw-sr">Action</span></th></tr></thead><tbody>
<?php foreach (($state['reviewers'] ?? []) as $reviewer) : $active = Reviewer::allowed((int) $reviewer->ID); ?><tr><td><strong><?php echo esc_html($reviewer->user_login); ?></strong></td><td><span class="badge <?php echo $active ? 'bg-green-lt' : 'bg-secondary-lt'; ?>"><?php echo $active ? 'Active' : 'Expired or revoked'; ?></span></td><td><?php echo esc_html(wp_date('j M Y', (int) get_user_meta($reviewer->ID, Reviewer::EXPIRES, true))); ?></td><td class="agw-row-actions"><?php if ($active) : ?><form method="post" action="<?php echo esc_url(Workspace::url()); ?>" data-confirm="Revoke this reviewer’s access and sign out their sessions?"><?php Workspace::nonce(); ?><input type="hidden" name="workspace_action" value="revoke_reviewer"><input type="hidden" name="reviewer_id" value="<?php echo (int) $reviewer->ID; ?>"><button class="btn btn-primary">Revoke access</button></form><?php endif; ?><form method="post" action="<?php echo esc_url(Workspace::url()); ?>" data-confirm="Issue a new password for this reviewer and sign out all existing sessions?"><?php Workspace::nonce(); ?><input type="hidden" name="workspace_action" value="renew_reviewer"><input type="hidden" name="reviewer_id" value="<?php echo (int) $reviewer->ID; ?>"><input type="hidden" name="reviewer_days" value="30"><button class="btn btn-primary">Reset password & renew</button></form></td></tr><?php endforeach; ?>
<?php if (empty($state['reviewers'])) : ?><tr><td colspan="4"><div class="empty agw-empty"><h3>No reviewers yet</h3></div></td></tr><?php endif; ?></tbody></table></div></section>
